using System;using System.IO;using System.Linq;using BeamScheduleFormatter;
class PieceTests {
static int checks;static void Check(bool b,string why){if(!b)throw new Exception(why);checks++;}static void Near(double a,double b,string why){Check(Math.Abs(a-b)<1e-8,why+" "+a+" != "+b);}static BeamRow Row(string[] bottom,string[] top){var r=new BeamRow{Mark="T-001",Leg="2L",Diameter="%%C10",RevisedSpacing="1 - 50mm, AND REST AT 200mm C/C"};r.Cells[0].Add("400");r.Cells[1].Add("600");for(int z=0;z<3;z++){r.Cells[z+2].Add(bottom[z]);r.Cells[z+5].Add(top[z]);}r.Cells[11].Add("2-%%C12 EF");return r;}
static void Main(string[] a){int[] ns={0,2,4,6};foreach(int l in ns)foreach(int m in ns)foreach(int r in ns){var row=Row(new[]{l+"-%%C20",m+"-%%C20",r+"-%%C20"}.Select(s=>s.StartsWith("0-")?"-":s).ToArray(),new[]{"2-%%C16","2-%%C16","2-%%C16"});var o=new EstimateOptions{FixedCurtailment=false};var e=EstimatorEngine.Calculate(row,row.Mark,8,o);var b=e.Lines.Where(x=>x.Part.StartsWith("Bottom")).ToList();Near(b.Where(x=>x.Part.EndsWith("CONTINUOUS")).Sum(x=>x.PiecesPerBeam),Math.Min(l,Math.Min(m,r)),"Wrong continuous count");Near(b.Sum(x=>x.Metres),l*2+m*4+r*2,"Zone material not conserved");Check(e.Lines.All(x=>x.Grade==40||x.Grade==60),"Unassigned grade");Near(e.Lines.Where(x=>x.Grade==40).Sum(x=>x.Kg)+e.Lines.Where(x=>x.Grade==60).Sum(x=>x.Kg),e.Total,"Grade totals do not reconcile");}
var mixed=Row(new[]{"4-%%C20","4-%%C16","4-%%C20"},new[]{"6-%%C20","4-%%C20","6-%%C20"});var no=EstimatorEngine.Calculate(mixed,mixed.Mark,8,new EstimateOptions{FixedCurtailment=false});Check(!no.Lines.Any(x=>x.Part=="Bottom CONTINUOUS"),"Different diameters incorrectly joined");Check(no.Lines.Count(x=>x.Part.StartsWith("Bottom CUT"))==3,"Mixed diameter pieces lost");Check(no.Lines.Single(x=>x.Part=="Top CONTINUOUS").PiecesPerBeam==4,"Top continuous mismatch");Check(no.Lines.Where(x=>x.Part.StartsWith("Top CUT")).Sum(x=>x.PiecesPerBeam)==4,"Top end cuts mismatch");
var adjacent=Row(new[]{"6-%%C20","6-%%C20","4-%%C20"},new[]{"4-%%C20","4-%%C20","4-%%C20"});var p=CalculationStore.Resolve(28,40,275,60,420);var result=EstimatorEngine.Calculate(adjacent,adjacent.Mark,8,new EstimateOptions{FixedCurtailment=false,LengthConfig=p,Anchorage=1});var cont=result.Lines.Single(x=>x.Part=="Bottom CONTINUOUS");double ld=p.Rounded(p.Values(20,false).Ld)/1000;Near(cont.Metres,4*(8+2*ld),"Continuous allowance applied more than once");var cut=result.Lines.Single(x=>x.Part=="Bottom CUT LEFT+MIDSPAN");Near(cut.Metres,2*(6+2*ld),"Adjacent zones were double cut");var hooked=EstimatorEngine.Calculate(adjacent,adjacent.Mark,8,new EstimateOptions{FixedCurtailment=false,LengthConfig=p,Anchorage=3,MainHook=90});var hc=hooked.Lines.Single(x=>x.Part=="Bottom CUT LEFT+MIDSPAN");var v=p.Values(20,false);Near(hc.CutLength,6+p.Rounded(v.Cut90)/1000+Math.Max(0,p.Rounded(v.Ldh)-(v.MainInside/2+20))/1000+ld,"Hook at an internal cut end or wrong development");
Console.WriteLine("PASS: "+checks+" piece reconciliation, diameter separation, continuous/adjacent cut allowances, hook ends and grade reconciliation checks.");}}
